import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import requests


class DatadogMetricsComparator:
    def __init__(
        self,
        api_key: Optional[str] = None,
        app_key: Optional[str] = None,
        site: Optional[str] = None,
        timeout: int = 30,
    ) -> None:
        self.api_key = api_key or os.environ["DATADOG_API_KEY"]
        self.app_key = app_key or os.environ["DATADOG_APP_KEY"]
        self.site = site or os.environ.get("DATADOG_SITE", "datadoghq.com")
        self.timeout = timeout
        self.base_url = f"https://api.{self.site}"

    def _headers(self) -> Dict[str, str]:
        return {
            "DD-API-KEY": self.api_key,
            "DD-APPLICATION-KEY": self.app_key,
            "Accept": "application/json",
        }

    @staticmethod
    def _to_epoch_seconds(value: Optional[Any]) -> int:
        if value is None:
            return int(datetime.now(timezone.utc).timestamp())
        if isinstance(value, (int, float)):
            return int(value)
        if isinstance(value, datetime):
            if value.tzinfo is None:
                value = value.replace(tzinfo=timezone.utc)
            return int(value.timestamp())
        raise TypeError("start/end must be epoch seconds, datetime, or None")

    def _query_series(
        self,
        metric: str,
        filter_scope: str,
        start: Any,
        end: Any,
        aggregator: str = "avg",
    ) -> Dict[str, Any]:
        from_ts = self._to_epoch_seconds(start)
        to_ts = self._to_epoch_seconds(end)

        query = f"{aggregator}:{metric}{{{filter_scope}}}"
        response = requests.get(
            f"{self.base_url}/api/v1/query",
            headers=self._headers(),
            params={
                "from": from_ts,
                "to": to_ts,
                "query": query,
            },
            timeout=self.timeout,
        )
        response.raise_for_status()
        data = response.json()

        series = data.get("series", [])
        if not series:
            raise ValueError(f"No series returned for query: {query}")

        first_series = series[0]
        points = first_series.get("pointlist", [])
        values = [p[1] for p in points if isinstance(p, list) and len(p) >= 2 and p[1] is not None]

        if not values:
            raise ValueError(f"No datapoints returned for query: {query}")

        return {
            "query": query,
            "metric": metric,
            "scope": filter_scope,
            "aggregator": aggregator,
            "start": from_ts,
            "end": to_ts,
            "series_name": first_series.get("display_name") or first_series.get("metric"),
            "point_count": len(values),
            "avg": sum(values) / len(values),
            "min": min(values),
            "max": max(values),
            "sum": sum(values),
            "latest": values[-1],
            "values": values,
        }

    def compare(
        self,
        metric: str,
        left_scope: str,
        right_scope: str,
        start: Optional[Any] = None,
        end: Optional[Any] = None,
        aggregator: str = "avg",
    ) -> Dict[str, Any]:
        if end is None:
            end = datetime.now(timezone.utc)
        if start is None:
            start = self._to_epoch_seconds(end) - int(timedelta(minutes=15).total_seconds())

        left = self._query_series(metric, left_scope, start, end, aggregator)
        right = self._query_series(metric, right_scope, start, end, aggregator)

        def pct_change(a: float, b: float) -> Optional[float]:
            if b == 0:
                return None
            return ((a - b) / b) * 100.0

        summary = {
            "metric": metric,
            "window": {"start": left["start"], "end": left["end"]},
            "aggregator": aggregator,
            "left": {
                "scope": left["scope"],
                "series_name": left["series_name"],
                "avg": left["avg"],
                "min": left["min"],
                "max": left["max"],
                "sum": left["sum"],
                "latest": left["latest"],
                "point_count": left["point_count"],
            },
            "right": {
                "scope": right["scope"],
                "series_name": right["series_name"],
                "avg": right["avg"],
                "min": right["min"],
                "max": right["max"],
                "sum": right["sum"],
                "latest": right["latest"],
                "point_count": right["point_count"],
            },
            "comparison": {
                "avg_delta": left["avg"] - right["avg"],
                "avg_pct_change_vs_right": pct_change(left["avg"], right["avg"]),
                "latest_delta": left["latest"] - right["latest"],
                "latest_pct_change_vs_right": pct_change(left["latest"], right["latest"]),
                "sum_delta": left["sum"] - right["sum"],
                "sum_pct_change_vs_right": pct_change(left["sum"], right["sum"]),
            },
        }
        return summary


def compare_metric_values(
    metric: str,
    left_scope: str,
    right_scope: str,
    start: Optional[Any] = None,
    end: Optional[Any] = None,
    aggregator: str = "avg",
    api_key: Optional[str] = None,
    app_key: Optional[str] = None,
    site: Optional[str] = None,
) -> Dict[str, Any]:
    comparator = DatadogMetricsComparator(
        api_key=api_key,
        app_key=app_key,
        site=site,
    )
    return comparator.compare(
        metric=metric,
        left_scope=left_scope,
        right_scope=right_scope,
        start=start,
        end=end,
        aggregator=aggregator,
    )
